import { test, expect, assert } from "vitest";

// generated by ./streamingFixture.globalSetup.tsx from React's streaming
// server renderer, driving a real custom element renderer
import streamedShell from "./generated/streamed-shell.html?raw";
import streamedAll from "./generated/streamed-all.html?raw";

/**
 * Loads HTML into a real, parsing document so that declarative shadow DOM
 * attaches and React's inline relocation script executes. `setHTMLUnsafe`
 * cannot be used here: it attaches declarative shadow roots but does not run
 * scripts, and the script is precisely what is under investigation.
 */
const loadDocument = (html: string): Promise<Document> =>
  new Promise((resolve, reject) => {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    iframe.srcdoc = `<!doctype html><html><body>${html}</body></html>`;
    iframe.addEventListener("load", () => {
      const doc = iframe.contentDocument;
      if (!doc) {
        reject(new Error("iframe had no document"));
        return;
      }
      // React schedules the relocation through requestAnimationFrame
      const win = iframe.contentWindow;
      assert(win);
      win.requestAnimationFrame(() =>
        win.requestAnimationFrame(() => setTimeout(() => resolve(doc), 0)),
      );
    });
    iframe.addEventListener("error", () => reject(new Error("iframe failed")));
    document.body.append(iframe);
  });

/**
 * These tests document how React's streaming SSR interacts with declarative
 * shadow DOM. They are assertions rather than prose so that a change in
 * React's behavior shows up as a failure instead of a stale design note.
 */

test("onAllReady emits the shadow template inline, with no relocation", () => {
  // the whole document is held back until every boundary resolves, so the
  // output is ordinary inline markup
  expect(streamedAll).toContain(
    '<sync-component title="Streaming Test" count="3"><template shadowrootmode="open">',
  );
  expect(streamedAll).not.toContain("hidden id=");
});

test("onShellReady delivers the boundary out of band, in a hidden container", () => {
  // the shell carries only the fallback...
  const shellEnd = streamedShell.indexOf("</div>");
  expect(streamedShell.slice(0, shellEnd)).toContain('id="fallback"');

  // ...and the real content arrives later inside a hidden div, followed by
  // the script that moves it into place
  expect(streamedShell).toMatch(/<div hidden id="S:0">/);
  expect(streamedShell).toContain('<template shadowrootmode="open">');
  expect(streamedShell).toContain("$RC(");
});

test("the streamed shadow template is still parsed, so the shadow root attaches", async () => {
  const doc = await loadDocument(streamedShell);

  const element = doc.querySelector("sync-component");
  assert(element, "the custom element must exist after relocation");

  // This is the finding. The suspended content is delivered as real HTML that
  // the parser processes in the hidden container, so the declarative shadow
  // root attaches there — at parse time, as the spec requires. React's script
  // then relocates the *element*, and an element carries its shadow root with
  // it. Nothing ever moves the <template> itself.
  expect(element.shadowRoot).not.toBeNull();
  expect(element.shadowRoot?.querySelector("h1")?.textContent).toBe(
    "Streaming Test",
  );
});

test("relocation moves the element into the shell, leaving no hidden container", async () => {
  const doc = await loadDocument(streamedShell);

  const app = doc.querySelector("#app");
  assert(app);
  expect(app.querySelector("sync-component")).not.toBeNull();
  expect(app.querySelector("#fallback")).toBeNull();
  expect(doc.querySelector("div[hidden]")).toBeNull();
});

test("light-dom children survive relocation alongside the shadow root", async () => {
  const doc = await loadDocument(streamedShell);

  const element = doc.querySelector("sync-component");
  assert(element);
  expect(element.querySelector("#light-dom")?.textContent).toBe(
    "light dom child",
  );
  // and the template left no stray node behind in the light DOM
  expect(element.querySelector("template")).toBeNull();
  expect(element.firstElementChild?.tagName).toBe("P");
});
